checks['payments'] = cur.execute("SELECT id, invoice_id, amount_cents, created_at FROM payments ORDER BY id").fetchall()
checks['orphans'] = cur.execute("SELECT id, invoice_id, amount_cents, created_at, reason FROM payment_orphans ORDER BY id").fetchall()
checks['shadow'] = cur.execute("SELECT id, status FROM _invoice_status_shadow ORDER BY id").fetchall()
checks['fk_violations'] = cur.execute("PRAGMA foreign_key_check").fetchall()
checks['postcheck'] = []
