        checks['postcheck'].append((stmt.splitlines()[0], cur.execute(stmt).fetchall()))

run_script('rollback.sql')
checks['rollback_invoice_columns'] = [row[1] for row in cur.execute("PRAGMA table_info(invoices)")]
checks['rollback_payment_columns'] = [row[1] for row in cur.execute("PRAGMA table_info(payments)")]
